export const rbAt = (t: string, i: i32): i32 => {
  const k = i * 3;
  const x = ((t.charCodeAt(k) - 40) << 12) | ((t.charCodeAt(k + 1) - 40) << 6) | (t.charCodeAt(k + 2) - 40);
  return x === 262143 ? RB_NIL : x - 131072;
};

/** racc's nil. */
export const RB_NIL: i32 = -2147483647;
